CREATE TABLE organisations (
    id UUID PRIMARY KEY, name VARCHAR(160) NOT NULL UNIQUE, created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE users (
    id UUID PRIMARY KEY, organisation_id UUID NOT NULL REFERENCES organisations(id), email VARCHAR(254) NOT NULL UNIQUE CHECK (email = lower(email)), password_hash VARCHAR(255) NOT NULL,
    role VARCHAR(32) NOT NULL CHECK (role IN ('CLIENT_USER','SECURITY_ANALYST','CASE_MANAGER','AUDITOR_ADMIN')), enabled BOOLEAN NOT NULL DEFAULT TRUE,
    failed_attempts INTEGER NOT NULL DEFAULT 0 CHECK (failed_attempts >= 0), locked_until TIMESTAMP WITH TIME ZONE, last_login_at TIMESTAMP WITH TIME ZONE, created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP, password_changed_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE cases (
    id UUID PRIMARY KEY, organisation_id UUID NOT NULL REFERENCES organisations(id), title VARCHAR(200) NOT NULL, description TEXT NOT NULL,
    category VARCHAR(32) NOT NULL CHECK (category IN ('RANSOMWARE_SIMULATION','PHISHING','DATA_EXPOSURE','MISCONFIGURATION','OTHER')),
    severity VARCHAR(16) NOT NULL CHECK (severity IN ('LOW','MEDIUM','HIGH','CRITICAL')),
    status VARCHAR(24) NOT NULL CHECK (status IN ('NEW','TRIAGED','IN_PROGRESS','AWAITING_CLIENT','RESOLVED','CLOSED')),
    owner_analyst_id UUID REFERENCES users(id), manager_id UUID REFERENCES users(id), created_by UUID NOT NULL REFERENCES users(id), retention_until TIMESTAMP WITH TIME ZONE, deleted_at TIMESTAMP WITH TIME ZONE,
    version BIGINT NOT NULL DEFAULT 0, created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE case_assignments (id UUID PRIMARY KEY, case_id UUID NOT NULL REFERENCES cases(id), organisation_id UUID NOT NULL REFERENCES organisations(id), analyst_id UUID NOT NULL REFERENCES users(id), assigned_by UUID NOT NULL REFERENCES users(id), assigned_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(case_id, analyst_id));
CREATE TABLE case_notes (id UUID PRIMARY KEY, case_id UUID NOT NULL REFERENCES cases(id), organisation_id UUID NOT NULL REFERENCES organisations(id), author_id UUID NOT NULL REFERENCES users(id), body TEXT NOT NULL, created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE remediation_actions (id UUID PRIMARY KEY, case_id UUID NOT NULL REFERENCES cases(id), organisation_id UUID NOT NULL REFERENCES organisations(id), author_id UUID NOT NULL REFERENCES users(id), description TEXT NOT NULL, status VARCHAR(16) NOT NULL CHECK (status IN ('OPEN','IN_PROGRESS','COMPLETE','CANCELLED')), due_date DATE, created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE evidence_files (id UUID PRIMARY KEY, case_id UUID NOT NULL REFERENCES cases(id), organisation_id UUID NOT NULL REFERENCES organisations(id), original_name_sanitised VARCHAR(255) NOT NULL, stored_name UUID NOT NULL UNIQUE, detected_mime VARCHAR(127) NOT NULL, size_bytes BIGINT NOT NULL CHECK (size_bytes >= 0), sha256 CHAR(64) NOT NULL, encrypted BOOLEAN NOT NULL, uploaded_by UUID NOT NULL REFERENCES users(id), created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE reports (id UUID PRIMARY KEY, case_id UUID NOT NULL REFERENCES cases(id), organisation_id UUID NOT NULL REFERENCES organisations(id), version INTEGER NOT NULL CHECK (version > 0), content TEXT NOT NULL, status VARCHAR(16) NOT NULL CHECK (status IN ('DRAFT','SUBMITTED','APPROVED')), generated_by UUID NOT NULL REFERENCES users(id), approved_by UUID REFERENCES users(id), created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(case_id, version));
CREATE TABLE audit_events (id BIGSERIAL PRIMARY KEY, ts TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP, actor_id UUID, actor_role VARCHAR(32), action VARCHAR(100) NOT NULL, target_type VARCHAR(64) NOT NULL, target_id UUID, outcome VARCHAR(16) NOT NULL CHECK (outcome IN ('SUCCESS','FAILURE','DENIED')), source_ip_hash VARCHAR(128), correlation_id UUID NOT NULL, details_json TEXT NOT NULL DEFAULT '{}', prev_hash CHAR(64), hash CHAR(64) NOT NULL);
CREATE INDEX idx_cases_org_status ON cases(organisation_id, status); CREATE INDEX idx_cases_owner ON cases(owner_analyst_id); CREATE INDEX idx_notes_case_org ON case_notes(case_id, organisation_id); CREATE INDEX idx_evidence_case_org ON evidence_files(case_id, organisation_id); CREATE INDEX idx_audit_ts ON audit_events(ts);
